# /// script
# dependencies = ["numpy", "pillow>=11"]
# ///
"""Publish frozen-camera photo / baseline / revised comparison evidence."""
import argparse,json,math,shutil
from pathlib import Path
import numpy as np
from PIL import Image,ImageDraw
ROOT=Path(__file__).resolve().parents[1]
p=argparse.ArgumentParser();p.add_argument('--after',type=Path,required=True);p.add_argument('--rake-deg',type=float,default=0);p.add_argument('--cartridge-height-mm',type=float,default=11.5);p.add_argument('--setback-mm',type=float,default=0);a=p.parse_args()
base=ROOT/'work/photo-comparison';out=base/'public';out.mkdir(parents=True,exist_ok=True)
cameras=json.loads((ROOT/'models/photo-cameras.json').read_text())
def project(point,v,size):
 az,el,roll=v[:3];ca,sa,ce,se=math.cos(az),math.sin(az),math.cos(el),math.sin(el)
 R=np.array([[ca,sa,0],[sa*se,-ca*se,-ce],[-sa*ce,ca*ce,-se]])
 cr,sr=math.cos(roll),math.sin(roll);R=np.array([[cr,-sr,0],[sr,cr,0],[0,0,1]])@R
 xyz=R@(np.array(point)-[0,0,.1])+v[3:6]
 return xyz[:2]/xyz[2]*math.exp(v[6])+np.array(size)/2
# Validation points withheld from the cabinet-only camera fit; selected by hand.
targets={'snuci':{'brightness':[499,353],'width_switch':[550,354],'power':[551,418],'top_lamp':[620,341]},'enter':{'brightness':[579,521],'width_switch':[613,519],'power':[617,568],'top_lamp':[654,511]},'bern':{'brightness':[474,331],'width_switch':[537,333],'power':[537,408],'top_lamp':[610,321]}}
original={'brightness':[-.067,-.140,.167],'width_switch':[-.040,-.140,.167],'power':[-.040,-.140,.128],'top_lamp':[-.006,-.135,.174]}
rows=[];measurements=[]
for view in cameras['views']:
 name=view['id'];photo=Image.open(ROOT/view['photo']).convert('RGB').resize(tuple(view['size']));photo.save(out/(name+'-photo.jpg'))
 before=Image.open(base/'before'/(name+'.png')).convert('RGB');after=Image.open(a.after/(name+'.png')).convert('RGB')
 before.save(out/(name+'-before.jpg'));after.save(out/(name+'-after.jpg'))
 sheet=Image.new('RGB',(3600,max(photo.height,before.height,after.height)+50),'#162029');d=ImageDraw.Draw(sheet)
 for i,(im,title) in enumerate([(photo,'Original photograph'),(before,'Before: same locked camera'),(after,'Revised: same locked camera')]):sheet.paste(im,(i*1200,50));d.text((i*1200+20,15),title,fill='white')
 sheet.save(out/(name+'-sheet.jpg'),quality=92)
 metrics=[]
 for feature,point in original.items():
  revised=[point[0]+.014,point[1]+a.setback_mm/1000+math.tan(math.radians(a.rake_deg))*(point[2]-.079),point[2]];target=np.array(targets[name][feature])
  bp=project(point,view['parameters'],view['size']);ap=project(revised,view['parameters'],view['size'])
  metrics.append({'feature':feature,'photo_px':target.tolist(),'before_px':bp.tolist(),'after_px':ap.tolist(),'before_error_px':float(np.linalg.norm(bp-target)),'after_error_px':float(np.linalg.norm(ap-target))})
 mb=float(np.mean([m['before_error_px'] for m in metrics]));ma=float(np.mean([m['after_error_px'] for m in metrics]))
 measurements.append({'view':name,'cabinet_camera_fit_rms_coordinate_px':view['cabinet_landmark_rms_px'],'mean_control_landmark_error_before_px':mb,'mean_control_landmark_error_after_px':ma,'features':metrics})
 rows.append(f'''<section><h2>{name.title()} photograph</h2><p><a href="{view['page']}">{view['credit']}</a>. Cabinet camera fit RMS: {view['cabinet_landmark_rms_px']:.1f} px per coordinate. Mean withheld control-point error: {mb:.1f} → {ma:.1f} px.</p><div class="triptych">'''+''.join(f'<figure><a href="{name}-{suffix}.jpg"><img src="{name}-{suffix}.jpg" alt="{title}"></a><figcaption>{title}</figcaption></figure>' for suffix,title in [('photo','Original photo'),('before','Before'),('after','Revised')])+f'''</div><p><a href="{name}-sheet.jpg">Full-resolution comparison sheet</a></p><details><summary>Overlay photograph with the revised render</summary><label>Render opacity <input type="range" min="0" max="100" value="50" oninput="this.parentElement.nextElementSibling.lastElementChild.style.opacity=this.value/100"></label><div class="overlay"><img src="{name}-photo.jpg" alt="Original photograph"><img src="{name}-after.jpg" alt="Revised render" style="opacity:.5"></div></details></section>''')
report={'camera_policy':'Cabinet-only fitted cameras frozen before refinement; interior control points withheld. No Trellis geometry used as ground truth.','uncertainty':'Hand-picked photo landmarks, unknown lens distortion and approximate cabinet corners; pixel errors diagnose alignment, not metrological accuracy.','views':measurements,'changes':{'front_rake_degrees':a.rake_deg,'front_assembly_setback_mm':a.setback_mm,'cartridge_presentation_height_mm':a.cartridge_height_mm,'crt_glass_recess_mm':[10.5,15] if a.rake_deg else None,'operator_controls_x_mm':14,'crt_surround_width_mm':[147,134],'crt_glass_width_mm':[120,108],'tape_opening_height_mm':[37,54],'key_count':[71,73],'upper_model_c_switches':[3,4],'side_vent_height_mm':[24,97]},'remaining':['Cabinet camera residuals are significant, especially Bern; roof/deck profile and fascia tilt still need a measured side view','L-shaped CMD/EXECUTE caps are now photo-traced; exact cap sculpting remains approximate','Photos show 3-switch single-language variants; the reconstruction follows the 4-switch Model C service drawing','Gray function keys now follow photographed groups; one additional main gray key needs identification','Unseen rear fittings, exact vent count and complete APL legends unverified']}
(out/'measurements.json').write_text(json.dumps(report,indent=2)+'\n')
shutil.copyfile(ROOT/'models/photo-cameras.json',out/'locked-cameras.json')
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>IBM 5100 · Photo comparisons</title><link rel="icon" href="data:,"><style>body{margin:0;background:#172027;color:#e6edf0;font:16px system-ui;line-height:1.5}main{max-width:1600px;padding:32px 24px;margin:auto}a{color:#e0ca91}h1{font-size:36px}h2{margin-top:40px}.triptych{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}figure{margin:0}img{display:block;width:100%}figcaption{padding:8px}section{border-top:1px solid #52616a;margin-top:32px}.overlay{position:relative;max-width:1200px}.overlay img:last-child{position:absolute;inset:0}.notice{padding:20px;background:#26343e;border-radius:8px}table{border-collapse:collapse}td,th{padding:8px 20px;border-bottom:1px solid #52616a;text-align:left}@media(max-width:750px){.triptych{grid-template-columns:1fr}}</style><main><a href="../">All previews</a> · <a href="../clean/">Improved interactive model</a><h1>IBM 5100 · Photo-matched refinement</h1><p>Three independent photographs, each with its own fitted camera. Before and revised renders use the same locked camera, lighting, exposure, and image dimensions.</p><div class="notice">Photos and IBM service drawings are evidence. The supplied Trellis reconstruction is excluded from the fit and geometry corrections. Camera alignment is approximate: yellow/cyan cabinet-fit diagnostics and full parameters are available in the <a href="locked-cameras.json">camera manifest</a>. Pixel differences also include lens distortion and imperfect cabinet shape.</div><h2>What was wrong</h2><ul><li>Operator controls were 14 mm too far left in the matched views.</li><li>The case-front edges were vertical; they now rake back by a photo-estimated 8°. The entire front assembly now sits behind the overhanging cover; the glass retains an additional 10.5–15 mm recess behind its bezel.</li><li>The CRT surround was too wide and its glass too large/low.</li><li>The tape opening was too short and too low; the cartridge incorrectly faced forward like a cassette.</li><li>The cartridge has subsequently been thickened 3.5× at user request; its current height is a presentation proportion, not a measured cartridge dimension.</li><li>The keyboard had two missing keys, overly broad black backing, and raised pads instead of separate recessed wells.</li><li>The complete keyboard now uses a traced photo-plane layout: row staggering, variable cap widths, L-shaped modifiers, gray function keys, a notched spacebar well, and separate numeric/operator gutters.</li><li>The keyboard mounting plane is now a distinct panel raised 5 mm above the lower case, carrying the key wells and instruction strip.</li><li>Side vents were only 24 mm high and stopped below the roof; photographs show long slots wrapping the upper corner.</li><li>The Model C service drawing has four upper switches; the baseline had only three.</li></ul><p><a href="measurements.json">Measurements, uncertainties, and remaining deviations</a></p><p>IBM maintenance manual SY31-0405-3: printed pages 2-9 (panel/layout), 2-39 (display and switches), 2-44 (Model C key layout), B-1 (F/S/H dimensions 445 / 609.6 / 203 mm). <a href="https://www.computercollector.com/archive/ibm/5100/5100_Maint_Info.pdf">Open manual</a>. The museum record uses 443 / 610 / 200 mm; small discrepancies are retained as uncertainty, rather than silently treated as exact.</p>ROWS<h2>Still unresolved</h2><p>Cabinet shape remains approximate; the camera-fit residuals show that roof/deck proportions and fascia tilt need further work. CMD and EXECUTE now have photo-traced L outlines; exact sculpting remains approximate. Single-language photo variants and German legends are not forced onto the Model C layout. The identified modifier and arrow keys are now gray with light legends. Rear fittings and complete APL legends are unverified.</p><footer><p>Original photographs are unmodified in the research archive. Display copies are resized; comparison sheets are labeled derivatives. Snuci: CC0. Bobo11 and Sandstein: <a href="https://creativecommons.org/licenses/by-sa/3.0/">CC BY-SA 3.0</a>; their resized photos and comparison sheets are provided under that license, with the source and author linked above.</p></footer></main></html>'''
(out/'index.html').write_text(page.replace('ROWS',''.join(rows)))
print(json.dumps([{'view':m['view'],'before':m['mean_control_landmark_error_before_px'],'after':m['mean_control_landmark_error_after_px']} for m in measurements]))
